create or replace TABLE KFL_PRODUCTION.DBP_DATA.GP (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH',
	GP_ID NUMBER(38,0) NOT NULL COMMENT 'Geschäftspartner - ID (Lieferanten - ID)',
	EINKAUFSORGANISATION_ID NUMBER(38,0) NOT NULL COMMENT '1000=Warenlieferant 5000=Frischelieferant ',
	DAT_VON DATE COMMENT 'Startdatum der Zusammenarbeit',
	DAT_BIS DATE COMMENT 'Ende der Gültigkeitsperiode. Format JJJJ-MM-TT ',
	ANLIEFERUNG_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'Kennzeichen der Anerkennung der L&S Anlieferungsbedingungen',
	GP_NAME VARCHAR(40) COLLATE 'en-ci' COMMENT 'Bezeichnung des Geschäftspartners',
	GP_STRASSE VARCHAR(40) COLLATE 'en-ci' COMMENT 'Strasse zur Adresse des Geschäftspartners',
	GP_PLZ VARCHAR(10) COLLATE 'en-ci' COMMENT 'Postleitzahl zur Adresse des Geschäftspartners',
	GP_ORT VARCHAR(40) COLLATE 'en-ci' COMMENT 'Ort, an dem der Geschäftspartner ansässig ist',
	LAND_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Land, in dem sich der Markt befindet. Hat immer Länge von 2 Zeichen (PL, CZ, DE,..). Im Quellsystem SAP hat das Feld 3 Zeichen, daher in der Länge 3 ',
	HGP_ID NUMBER(38,0) COMMENT 'Nummer des Hauptlieferanten(Kreditors) zu einem Unterlieferanten, i.d.R. die ersten 6 Stellen der siebenstelligen Lieferantennummer',
	ZEK_ID VARCHAR(3) COMMENT 'Zentraleinkäufer - ID des Einkaufsmitarbeiters, der für einen Lieferanten zuständig ist.',
	LIEFERZEIT NUMBER(38,0) COMMENT 'Standard Lieferzeit in Tagen für einen Lieferanten',
	ZAHLUNGSZIEL_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'mit einem Lieferanten vereinbartes Zahlungsziel wird über die Lookup-Tabelle l_zahlungsziel referenziert',
	AGB_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'Juristische Art der Zusammenarbeit:  L: L&S - AGB G: gesetzliche AGB blank: ohne Angabe',
	ISO_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'Isonorm, ist der Lieferant nach ISO zertifiziert',
	EIGENVERPACKUNG_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'Kennzeichen für Eigenverpackung (J/N)',
	EIGENMARKE_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'handelt es sich um einen Eigenmarken-Lieferanten',
	AUDIT_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'Möglichkeit eines Audit',
	AUDIT_DAT DATE COMMENT 'Datum des letzten Audit. Format JJJJ-MM-TT',
	HERST_FG NUMBER(38,0) COMMENT 'Kennzeichnet, ob es sich bei einem Lieferanten gleichzeitig auch um einen Hersteller handelt',
	ZAHLART_ID VARCHAR(1) COLLATE 'en-ci' COMMENT 'Eindeutiger Schluessel der Zahlarten, (z. B. m fuer Markant)',
	RETOUR_SPERR_FG NUMBER(38,0) COMMENT 'Dieses Flag kennzeichnet ob der Lieferant für Retouren gesperrt ist. FG = 1: Lieferant ist gesperrt.',
	SYSTEM_ID NUMBER(38,0) COMMENT 'Die System ID kennzeichnet das Quellsystem der Daten (z. B. SAP PR1).',
	GP_BRANCHE_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'Eindeutiger Schuessel der Lieferantenbranchen (z. B. CO13 fuer Milch, Mopro). In KMO ist die Quelle bsch_id aus t016t, in DE ist die Quelle zzrp_invcat',
	WEWA_FG NUMBER(38,0) COMMENT 'Dieses Flag gibt an, ob es sich bei diesem Lieferanten um einen für die wewa-Schnittstelle relevanten Geschäftspartner handelt',
	LOESCH_FG NUMBER(38,0) COMMENT 'Löschkennzeichen für den Lieferanten (1 ist gelöscht)',
	REGION_ID NUMBER(38,0) NOT NULL COMMENT 'Region eines Landes, z.Bsp. Hessen, Kärnten. Wird im DWH als künstlicher Schlüssel über die SAP-Region gebildet ',
	MIN_PAL_FAKTOR_LKW NUMBER(9,2) NOT NULL DEFAULT 0 COMMENT 'Mindestpalettenfaktor pro LKW aus lfm1.minbw',
	GLN_BBNR VARCHAR(10) NOT NULL COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Basisnummer der GLN. Quelle ist lfa1.bbbnr',
	GLN_BSNR VARCHAR(10) NOT NULL COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Individueller Nummernteil der GLN. Quelle ist lfa1.bbsnr',
	GLN_BUBKZ VARCHAR(1) NOT NULL COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Prüfziffer der GLN. Quelle ist lfa1.bubkz',
	BREITENGRAD NUMBER(38,16) COMMENT 'Breitengrad aus dem GIS-System (Latitude)',
	LAENGENGRAD NUMBER(38,16) COMMENT 'Längengrad aus dem GIS-System (Longitude)',
	GP_NAME_LAT VARCHAR(80) NOT NULL COLLATE 'en-ci' DEFAULT '0' COMMENT 'Lateinische Bezeichnung Lieferant',
	IVN NUMBER(38,0) COMMENT 'Internationale Verhandler Nummer',
	ISD_FG NUMBER(38,0) COMMENT 'Flag: Internationale Sortimentsdisposition',
	MARKANT_ID VARCHAR(2) NOT NULL DEFAULT '  ' COMMENT 'ID Markantabrechnung',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_GP primary key (MANDANT_ID, GP_ID)
)COMMENT='TP2_AIS - Geschaeftspartner - MULTISET'
;